import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.notifications.api.MailTransport;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

class OrderCancellationMailTest {

    static class RecordingMail implements MailTransport {
        final List<String[]> sent = new ArrayList<>();

        @Override
        public void deliver(String address, String subject, String body) {
            sent.add(new String[] {address, subject, body});
        }
    }

    static class RecordingConfig {
        @Bean
        @Primary
        RecordingMail recordingMail() {
            return new RecordingMail();
        }
    }

    @Test
    void cancellingAnOrderMailsTheCustomerOnce() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, RecordingConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            CustomerFacade customers = shop.getBean(CustomerFacade.class);
            RecordingMail mail = shop.getBean(RecordingMail.class);

            customers.register("c-9", "anna@example.com");
            String id = orders.place("c-9", Money.pln(500), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, mail.sent.size());
            String[] message = mail.sent.get(0);
            assertEquals("anna@example.com", message[0]);
            assertTrue(message[1].contains(id));
        }
    }

    @Test
    void noMailWhenTheCustomerHasNoRegisteredAddress() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, RecordingConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            RecordingMail mail = shop.getBean(RecordingMail.class);

            String id = orders.place("nobody", Money.pln(500), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);

            assertEquals(0, mail.sent.size());
        }
    }
}
}
